<?php if(!isAdmin()){flash('error','Acesso restrito.');redirect('index.php?page=dashboard');}
$keys=['company_name','company_document','company_phone','company_address','store_number','terminal_number','pix_key','receipt_footer'];
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();foreach($keys as $k){$pdo->prepare('INSERT INTO settings(`key`,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)')->execute([$k,trim($_POST[$k]??'')]);}audit($pdo,'update','settings',null,'Configurações do sistema atualizadas');flash('success','Configurações atualizadas.');redirect('index.php?page=settings');}
$title='Configurações';require __DIR__.'/../../includes/header.php';?>
